values ($paper_seed$c10-hist-ch1-p1$paper_seed$, 8, $paper_seed$A$paper_seed$, $paper_seed$mcq$paper_seed$, 1, $paper_seed$The female allegory that came to represent the German nation was:$paper_seed$, null, $paper_seed$["Marianne","Britannia","Germania","Liberty"]$paper_seed$::jsonb, 2, null, null);

insert into questions (paper_id, position, section_label, qtype, marks, prompt, source_id, options, correct_index, scheme, hint)
values ($paper_seed$c10-hist-ch1-p1$paper_seed$, 9, $paper_seed$B$paper_seed$, $paper_seed$text$paper_seed$, 2, $paper_seed$What was the main intention of the conservatives who drew up the Treaty of Vienna in 1815?$paper_seed$, null, null, null, $paper_seed${"model_answer":"The Treaty of Vienna of 1815 was drawn up with the object of undoing most of the changes that had come about in Europe during the Napoleonic wars. The Bourbon dynasty was restored to power in France, France lost the territories it had annexed, and a series of states were set up on its boundaries to prevent French expansion in future. The main intention was to restore the monarchies that had been overthrown by Napoleon and to create a new conservative order in Europe.","points":[{"point":"To undo the changes of the Napoleonic wars: the Bourbon dynasty was restored and France lost its annexed territories, with new states set up on its boundaries to prevent future expansion","marks":1},{"point":"To restore the monarchies overthrown by Napoleon and create a new conservative order in Europe","marks":1}]}$paper_seed$::jsonb, $paper_seed$2 marks = 2 points — what they undid, and the new order they wanted.$paper_seed$);

insert into questions (paper_id, position, section_label, qtype, marks, prompt, source_id, options, correct_index, scheme, hint)
values ($paper_seed$c10-hist-ch1-p1$paper_seed$, 10, $paper_seed$B$paper_seed$, $paper_seed$text$paper_seed$, 2, $paper_seed$Why did Metternich describe Mazzini as 'the most dangerous enemy of our social order'?$paper_seed$, null, null, null, $paper_seed${"model_answer":"Mazzini believed that nations were the natural units of mankind, and he wanted Italy to be forged into a single unified democratic republic — not a patchwork of kingdoms. His opposition to monarchy struck at the very basis of the conservative order that Metternich defended. Moreover, through the secret societies he founded — Young Italy and Young Europe — his vision inspired young revolutionaries far beyond Italy. That is why Metternich described him as 'the most dangerous enemy of our social order'.","points":[{"point":"Mazzini opposed monarchy and dreamed of unified democratic republics, which directly threatened the conservative order of kings and empires","marks":1},{"point":"Through his secret societies (Young Italy, Young Europe) his ideas inspired revolutionaries across Europe","marks":1}]}$paper_seed$::jsonb, null);

insert into questions (paper_id, position, section_label, qtype, marks, prompt, source_id, options, correct_index, scheme, hint)
values ($paper_seed$c10-hist-ch1-p1$paper_seed$, 11, $paper_seed$B$paper_seed$, $paper_seed$text$paper_seed$, 2, $paper_seed$Mention any two attributes seen in the visual representation of Germania, and what they stand for.$paper_seed$, null, null, null, $paper_seed${"model_answer":"Germania, the female allegory of the German nation, is shown with symbolic attributes. Her crown of oak leaves stands for heroism, since the German oak was a symbol of courage. The sword in her hand stands for readiness to fight, while the olive branch wrapped around it signifies a willingness to make peace. The broken chains at her feet represent freedom, and the black, red and gold tricolour is the flag of the liberal-nationalists of 1848.","points":[{"point":"Any correct attribute + meaning, e.g. crown of oak leaves = heroism; sword = readiness to fight; broken chains = being freed","marks":1},{"point":"A second correct attribute + meaning, e.g. breastplate with eagle = strength of the German empire; olive branch around the sword = willingness to make peace; black, red and gold tricolour = the flag of the liberal-nationalists of 1848","marks":1}]}$paper_seed$::jsonb, null);

insert into questions (paper_id, position, section_label, qtype, marks, prompt, source_id, options, correct_index, scheme, hint)
values ($paper_seed$c10-hist-ch1-p1$paper_seed$, 12, $paper_seed$C$paper_seed$, $paper_seed$text$paper_seed$, 3, $paper_seed$Describe any three measures introduced by the French revolutionaries to create a sense of collective identity among the French people.$paper_seed$, null, null, null, $paper_seed${"model_answer":"The French revolutionaries introduced various measures to create a sense of collective identity among the French people. The ideas of la patrie (the fatherland) and le citoyen (the citizen) emphasised the notion of a united community enjoying equal rights under a constitution. A new French flag, the tricolour, was chosen to replace the royal standard. The Estates General was elected by the body of active citizens and renamed the National Assembly. New hymns were composed, oaths taken and martyrs commemorated, all in the name of the nation. A centralised administrative system made uniform laws for all citizens, internal customs duties were abolished, uniform weights and measures were adopted, and regional dialects were discouraged in favour of French as the common language of the nation.","points":[{"point":"The ideas of la patrie (the fatherland) and le citoyen (the citizen) emphasised a united community with equal rights under a constitution","marks":1},{"point":"A new French flag, the tricolour, replaced the royal standard; the Estates General was renamed the National Assembly and was elected by citizens","marks":1},{"point":"New hymns were composed, oaths taken and martyrs commemorated in the name of the nation; a centralised administration made uniform laws, weights and measures, and promoted the French language","marks":1}]}$paper_seed$::jsonb, $paper_seed$3 marks = 3 distinct measures. Name the measure, don't just describe the mood.$paper_seed$);

insert into questions (paper_id, position, section_label, qtype, marks, prompt, source_id, options, correct_index, scheme, hint)
values ($paper_seed$c10-hist-ch1-p1$paper_seed$, 13, $paper_seed$C$paper_seed$, $paper_seed$text$paper_seed$, 3, $paper_seed$Explain any three features of the Napoleonic Code (Civil Code of 1804).$paper_seed$, null, null, null, $paper_seed${"model_answer":"The Civil Code of 1804, usually known as the Napoleonic Code, did away with all privileges based on birth and established equality before the law. It also secured the right to property. When Napoleon carried the Code to the regions under French control — the Dutch Republic, Switzerland, Italy and Germany — he simplified administrative divisions, abolished the feudal system and freed peasants from serfdom and manorial dues. In the towns, guild restrictions were removed, and transport and communication systems were improved.","points":[{"point":"Did away with all privileges based on birth, established equality before the law","marks":1},{"point":"Secured the right to property","marks":1},{"point":"In the territories under French control it simplified administrative divisions, abolished the feudal system, freed peasants from serfdom and manorial dues, and removed guild restrictions in towns","marks":1}]}$paper_seed$::jsonb, null);

insert into questions (paper_id, position, section_label, qtype, marks, prompt, source_id, options, correct_index, scheme, hint)
values ($paper_seed$c10-hist-ch1-p1$paper_seed$, 14, $paper_seed$D$paper_seed$, $paper_seed$text$paper_seed$, 5, $paper_seed$Explain the process by which the unification of Germany was achieved.$paper_seed$, null, null, null, $paper_seed${"model_answer":"Nationalist feelings were widespread among middle-class Germans, who in 1848 attempted to unite the different regions of the German confederation into a nation-state governed by an elected parliament. This liberal initiative was, however, repressed by the combined forces of the monarchy and the military, supported by the large landowners (Junkers) of Prussia. From then on, Prussia took the leadership of the movement for national unification. Its Chief Minister, Otto von Bismarck, was the architect of the process, carried out with the help of the Prussian army and bureaucracy. Three wars over seven years — with Denmark, Austria and France — ended in Prussian victory and completed the process of unification. In January 1871, the Prussian king, William I, was proclaimed German Emperor in a ceremony held at Versailles. The new German state placed strong emphasis on modernising the currency, banking, legal and judicial systems, and Prussian measures and practices often became a model for the rest of Germany.","points":[{"point":"Nationalist feelings were widespread among middle-class Germans, who in 1848 tried to unite the German confederation into a nation-state, but the attempt was repressed by the monarchy and military, supported by large landowners of Prussia","marks":1},{"point":"After 1848, Prussia took on the leadership of the movement for national unification","marks":1},{"point":"Its Chief Minister Otto von Bismarck was the architect of the process, carried out with the help of the Prussian army and bureaucracy","marks":1},{"point":"Three wars over seven years — with Denmark, Austria and France — ended in Prussian victory and completed unification","marks":1},{"point":"In January 1871, the Prussian king William I was proclaimed German Emperor at Versailles; the new German state emphasised modernising the currency, banking and legal systems, with Prussian measures often serving as the model","marks":1}]}$paper_seed$::jsonb, $paper_seed$5 marks = 5 points in sequence — 1848 failure, Prussia's lead, Bismarck's method, the three wars, and the proclamation of 1871.$paper_seed$);

