insert into questions (paper_id, position, section_label, qtype, marks, prompt, source_id, options, correct_index, scheme, hint)
values ($paper_seed$c10-hist-ch1-p1$paper_seed$, 17, $paper_seed$E$paper_seed$, $paper_seed$text$paper_seed$, 2, $paper_seed$Explain two reasons why the social basis of the Frankfurt parliament eroded.$paper_seed$, $paper_seed$src-frankfurt$paper_seed$, null, null, $paper_seed${"model_answer":"The social basis of the Frankfurt parliament eroded for two main reasons. First, the parliament was dominated by the middle classes, who resisted the demands of workers and artisans and consequently lost their support. Second, the opposition of the aristocracy and the military became stronger; deprived of popular support and facing armed opposition, the assembly was finally forced to disband when troops were called in.","points":[{"point":"The parliament was dominated by the middle classes, who resisted the demands of workers and artisans and so lost their support","marks":1},{"point":"The opposition of the aristocracy and the military grew stronger, and in the end troops disbanded the assembly","marks":1}]}$paper_seed$::jsonb, null);



